import java.security.*; import java.util.Base64; import java.nio.file.*; public class GenKeys { public static void main(String[] args) throws Exception { KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA"); kpg.initialize(2048); KeyPair kp = kpg.generateKeyPair(); String priv = "-----BEGIN PRIVATE KEY-----\n" + Base64.getMimeEncoder(64, new byte[]{10}).encodeToString(kp.getPrivate().getEncoded()) + "\n-----END PRIVATE KEY-----\n"; String pub = "-----BEGIN PUBLIC KEY-----\n" + Base64.getMimeEncoder(64, new byte[]{10}).encodeToString(kp.getPublic().getEncoded()) + "\n-----END PUBLIC KEY-----\n"; Files.writeString(Path.of(args[0]), priv); Files.writeString(Path.of(args[1]), pub); System.out.println("done"); } }